/* Lux Omni — Dropbox Bring Your Own Cloud integration.
 * Browser-only OAuth uses authorization-code + PKCE. Never add an app secret here.
 * The PDF editor must supply an exported Blob before Sync can overwrite a source file.
 */
(function () {
  "use strict";

  const DROPBOX_APP_KEY = "8vfyy6u50amp4py";
  const REQUIRED_SCOPES = [
    "files.metadata.read",
    "files.content.read",
    "files.content.write"
  ];
  const SUPPORTED_FILE_EXTENSIONS = new Set([
    ".pdf", ".md", ".jpg", ".jpeg", ".png", ".svg", ".webp", ".gif"
  ]);

  const STORAGE = {
    accessToken: "lux-dropbox-access-token",
    expiresAt: "lux-dropbox-access-token-expires-at",
    codeVerifier: "lux-dropbox-code-verifier",
    oauthState: "lux-dropbox-oauth-state"
  };

  const redirectUri = window.location.origin + window.location.pathname;
  const dropboxButton = document.querySelector("#dropbox-connect");
  const syncButton = document.querySelector("#dropbox-sync");
  const accountToggle = document.querySelector("#dropbox-account-toggle");
  const accountMenu = document.querySelector("#dropbox-account-menu");
  const accountMenuDescription = document.querySelector("#dropbox-account-menu-description");
  const menuConnectButton = document.querySelector("#dropbox-menu-connect");
  const menuDisconnectButton = document.querySelector("#dropbox-menu-disconnect");
  const disconnectConfirmation = document.querySelector("#dropbox-disconnect-confirmation");
  const disconnectCancelButton = document.querySelector("#dropbox-disconnect-cancel");
  const disconnectConfirmButton = document.querySelector("#dropbox-disconnect-confirm");
  const accountFeedback = document.querySelector("#dropbox-account-feedback");
  const statusText = document.querySelector("#dropbox-status-text");
  const modal = document.querySelector("#dropbox-modal");
  const modalCloseButton = document.querySelector("#dropbox-modal-close");
  const modalStatus = document.querySelector("#dropbox-modal-status");
  const modalLoading = document.querySelector("#dropbox-modal-loading");
  const modalLoadingText = document.querySelector("#dropbox-modal-loading-text");
  const modalFileList = document.querySelector("#dropbox-modal-file-list");
  const modalSelectButton = document.querySelector("#dropbox-modal-select");
  const modalCancelButton = document.querySelector("#dropbox-modal-cancel");
  const accessibleStatus = document.querySelector("#dropbox-accessible-status");
  const workspace = document.querySelector(".workspace");

  let dbx = null;
  let activeFilePathLower = null;
  let activeFileName = null;
  let activeFileKind = null;
  let activeSourcePdfBlob = null;
  let selectedDropboxFile = null;
  let selectedDropboxButton = null;
  let editedPdfBlob = null;
  let previewObjectUrl = null;
  let isListingFiles = false;
  let isOpeningFile = false;
  let isSyncing = false;
  let lastFocusedElement = null;
  let syncFeedbackTimer = null;
  let isDisconnecting = false;

  function setStatus(text, kind) {
    if (modalStatus) {
      modalStatus.textContent = text;
      if (kind) modalStatus.dataset.kind = kind;
      else delete modalStatus.dataset.kind;
    }
    if (accessibleStatus) accessibleStatus.textContent = text;
  }

  function setConnectionStatus(state) {
    const labels = {
      "not-connected": "Not connected",
      "connected": "Connected",
      "connection-failed": "Connection failed",
      "uploading": "Uploading",
      "saved": "Saved"
    };
    const normalizedState = labels[state] ? state : "not-connected";
    if (statusText) {
      statusText.dataset.state = normalizedState;
      statusText.textContent = labels[normalizedState];
    }
    if (accountToggle) {
      accountToggle.setAttribute("aria-label", "Dropbox account: " + labels[normalizedState]);
      accountToggle.title = "Dropbox account: " + labels[normalizedState];
    }

    if (accountMenuDescription) {
      if (dbx && (normalizedState === "connected" || normalizedState === "saved" || normalizedState === "uploading")) {
        accountMenuDescription.textContent = "Your Dropbox account is connected to Lux Omni.";
      } else if (normalizedState === "connection-failed") {
        accountMenuDescription.textContent = dbx
          ? "The last Dropbox request failed. You can disconnect this session or try again."
          : "Dropbox could not connect. Try connecting again.";
      } else {
        accountMenuDescription.textContent = "Connect your Dropbox account to browse and open supported files.";
      }
    }

    if (menuConnectButton) menuConnectButton.hidden = Boolean(dbx);
    if (menuDisconnectButton) menuDisconnectButton.hidden = !dbx;
  }

  function setAccountFeedback(text, kind) {
    if (!accountFeedback) return;
    accountFeedback.textContent = text || "";
    accountFeedback.hidden = !text;
    if (kind) accountFeedback.dataset.kind = kind;
    else delete accountFeedback.dataset.kind;
  }

  function setAccountMenuOpen(isOpen) {
    if (!accountMenu || !accountToggle) return;
    accountMenu.hidden = !isOpen;
    accountToggle.setAttribute("aria-expanded", String(isOpen));
    if (!isOpen) {
      if (disconnectConfirmation) disconnectConfirmation.hidden = true;
      if (menuDisconnectButton) menuDisconnectButton.hidden = !dbx;
      if (disconnectConfirmButton) {
        disconnectConfirmButton.disabled = false;
        disconnectConfirmButton.textContent = "Disconnect";
      }
      if (disconnectCancelButton) disconnectCancelButton.disabled = false;
    } else {
      setAccountFeedback("", "");
      if (disconnectConfirmation) disconnectConfirmation.hidden = true;
      if (menuDisconnectButton) menuDisconnectButton.hidden = !dbx;
      window.requestAnimationFrame(function () {
        (dbx ? menuDisconnectButton : menuConnectButton)?.focus();
      });
    }
  }

  function updateModalSelectButton() {
    if (modalSelectButton) {
      modalSelectButton.disabled = !dbx || !selectedDropboxFile || isListingFiles || isOpeningFile;
    }
    if (modalCancelButton) modalCancelButton.disabled = isOpeningFile;
    if (modalCloseButton) modalCloseButton.disabled = isOpeningFile;
  }

  function clearDropboxSelection() {
    if (selectedDropboxButton) {
      selectedDropboxButton.classList.remove("selected");
      selectedDropboxButton.setAttribute("aria-pressed", "false");
    }
    selectedDropboxFile = null;
    selectedDropboxButton = null;
    updateModalSelectButton();
  }

  function setModalLoading(isLoading) {
    if (modalLoading) modalLoading.hidden = !isLoading;
    updateModalSelectButton();
  }

  function setModalOpen(isOpen) {
    if (!modal) return;

    if (isOpen) {
      lastFocusedElement = document.activeElement;
      modal.hidden = false;
      document.body.classList.add("dropbox-modal-open");
      window.requestAnimationFrame(function () {
        modalCloseButton?.focus();
      });
      return;
    }

    modal.hidden = true;
    document.body.classList.remove("dropbox-modal-open");
    setModalLoading(false);
    clearDropboxSelection();
    if (lastFocusedElement && typeof lastFocusedElement.focus === "function") {
      lastFocusedElement.focus();
    } else {
      dropboxButton?.focus();
    }
  }

  function updateSyncButton() {
    if (!syncButton) return;

    // Dropbox overwrite sync remains available only for a successfully opened PDF.
    const canSyncActivePdf = Boolean(dbx && activeFilePathLower && activeFileKind === "pdf");
    syncButton.hidden = !canSyncActivePdf;
    syncButton.disabled = !canSyncActivePdf || isSyncing || isOpeningFile;
    if (!isSyncing && syncButton.textContent === "Syncing...") {
      syncButton.textContent = "Sync";
    }
  }

  function clearSessionCredentials(status = "not-connected") {
    try {
      sessionStorage.removeItem(STORAGE.accessToken);
      sessionStorage.removeItem(STORAGE.expiresAt);
      sessionStorage.removeItem(STORAGE.codeVerifier);
      sessionStorage.removeItem(STORAGE.oauthState);
    } catch (_) {
      // Ignore storage cleanup failures; the in-memory client is still cleared.
    }

    dbx = null;
    activeFilePathLower = null;
    activeFileName = null;
    activeFileKind = null;
    activeSourcePdfBlob = null;
    editedPdfBlob = null;
    setConnectionStatus(status);
    updateSyncButton();
  }

  function createState() {
    const bytes = new Uint8Array(32);
    window.crypto.getRandomValues(bytes);
    return Array.from(bytes, function (value) {
      return value.toString(16).padStart(2, "0");
    }).join("");
  }

  function sdkAvailable() {
    return Boolean(window.Dropbox && window.Dropbox.Dropbox && window.Dropbox.DropboxAuth);
  }

  async function connectDropbox() {
    setConnectionStatus("not-connected");
    if (!DROPBOX_APP_KEY || DROPBOX_APP_KEY === "YOUR_DROPBOX_APP_KEY") {
      setModalOpen(true);
      setConnectionStatus("connection-failed");
      setStatus("Setup needed: add your Dropbox App Key in dropbox-integration.js.", "error");
      return;
    }

    if (!sdkAvailable()) {
      setModalOpen(true);
      setConnectionStatus("connection-failed");
      setConnectionStatus("connection-failed");
      setStatus("The Dropbox SDK could not be loaded. Refresh the page and try again.", "error");
      return;
    }

    if (!window.crypto || !window.crypto.subtle || !window.crypto.getRandomValues) {
      setModalOpen(true);
      setConnectionStatus("connection-failed");
      setStatus("This browser does not provide the Web Crypto API required by Dropbox PKCE.", "error");
      return;
    }

    try {
      const auth = new window.Dropbox.DropboxAuth({ clientId: DROPBOX_APP_KEY });
      const state = createState();
      const authUrl = await auth.getAuthenticationUrl(
        redirectUri,
        state,
        "code",
        "online",
        REQUIRED_SCOPES,
        undefined,
        true
      );

      sessionStorage.setItem(STORAGE.codeVerifier, auth.getCodeVerifier());
      sessionStorage.setItem(STORAGE.oauthState, state);
      setStatus("Redirecting to Dropbox to connect your account…");
      window.location.assign(authUrl);
    } catch (error) {
      setModalOpen(true);
      setConnectionStatus("connection-failed");
      setStatus("Could not start Dropbox authorization: " + errorMessage(error), "error");
    }
  }

  function removeOAuthParametersFromAddressBar(url) {
    url.searchParams.delete("code");
    url.searchParams.delete("state");
    url.searchParams.delete("error");
    url.searchParams.delete("error_description");
    const newAddress = url.pathname + (url.search ? url.search : "") + url.hash;
    window.history.replaceState({}, document.title, newAddress);
  }

  async function handleOAuthCallback() {
    const url = new URL(window.location.href);
    const code = url.searchParams.get("code");
    const returnedState = url.searchParams.get("state");
    const oauthError = url.searchParams.get("error_description") || url.searchParams.get("error");

    if (!code && !oauthError) return false;

    removeOAuthParametersFromAddressBar(url);

    if (oauthError) {
      sessionStorage.removeItem(STORAGE.codeVerifier);
      sessionStorage.removeItem(STORAGE.oauthState);
      setModalOpen(true);
      setConnectionStatus("connection-failed");
      setStatus("Dropbox authorization was not completed: " + oauthError, "error");
      return true;
    }

    let expectedState;
    let verifier;
    try {
      expectedState = sessionStorage.getItem(STORAGE.oauthState);
      verifier = sessionStorage.getItem(STORAGE.codeVerifier);
    } catch (_) {
      setModalOpen(true);
      setConnectionStatus("connection-failed");
      setStatus("This browser could not read the temporary OAuth session. Please connect again.", "error");
      return true;
    }

    if (!returnedState || !expectedState || returnedState !== expectedState || !verifier) {
      sessionStorage.removeItem(STORAGE.codeVerifier);
      sessionStorage.removeItem(STORAGE.oauthState);
      setModalOpen(true);
      setConnectionStatus("connection-failed");
      setStatus("Dropbox sign-in could not be verified. Please connect again.", "error");
      return true;
    }

    if (!sdkAvailable()) {
      setModalOpen(true);
      setConnectionStatus("connection-failed");
      setStatus("The Dropbox SDK could not be loaded while completing sign-in.", "error");
      return true;
    }

    try {
      const auth = new window.Dropbox.DropboxAuth({ clientId: DROPBOX_APP_KEY });
      auth.setCodeVerifier(verifier);
      const tokenResponse = await auth.getAccessTokenFromCode(redirectUri, code);
      const result = tokenResponse && tokenResponse.result;

      if (!result || !result.access_token) {
        throw new Error("Dropbox did not return an access token.");
      }

      const expiresInSeconds = Number(result.expires_in) || 14400;
      sessionStorage.setItem(STORAGE.accessToken, result.access_token);
      sessionStorage.setItem(
        STORAGE.expiresAt,
        String(Date.now() + Math.max(60, expiresInSeconds) * 1000)
      );
      sessionStorage.removeItem(STORAGE.codeVerifier);
      sessionStorage.removeItem(STORAGE.oauthState);

      initializeClient(result.access_token);
      setModalOpen(true);
      setStatus("Connected. Loading your Dropbox PDFs…");
      await listDropboxPdfs();
      return true;
    } catch (error) {
      sessionStorage.removeItem(STORAGE.codeVerifier);
      sessionStorage.removeItem(STORAGE.oauthState);
      setModalOpen(true);
      setConnectionStatus("connection-failed");
      setStatus("Could not complete Dropbox sign-in: " + errorMessage(error), "error");
      return true;
    }
  }

  function initializeClient(accessToken) {
    dbx = new window.Dropbox.Dropbox({ accessToken: accessToken });
    setConnectionStatus("connected");
    updateSyncButton();
  }

  function restoreSession() {
    let token;
    let expiresAt;

    try {
      token = sessionStorage.getItem(STORAGE.accessToken);
      expiresAt = Number(sessionStorage.getItem(STORAGE.expiresAt));
    } catch (_) {
      setConnectionStatus("connection-failed");
      setStatus("Session storage is unavailable. Enable it to connect Dropbox in this tab.", "error");
      return;
    }

    if (!token || !expiresAt || expiresAt <= Date.now() + 15000) {
      if (token) clearSessionCredentials();
      updateSyncButton();
      return;
    }

    if (!sdkAvailable()) {
      setConnectionStatus("connection-failed");
      setConnectionStatus("connection-failed");
      setStatus("The Dropbox SDK could not be loaded. Refresh the page and try again.", "error");
      return;
    }

    initializeClient(token);
  }

  function errorMessage(error) {
    if (error && error.error && error.error.error_summary) return error.error.error_summary;
    if (error && error.message) return error.message;
    return String(error || "Unknown error");
  }

  function handleRequestError(error) {
    setConnectionStatus("connection-failed");
    if (error && (error.status === 401 || error.status === 400)) {
      clearSessionCredentials("connection-failed");
      setStatus("Your Dropbox session may have expired. Click Dropbox to connect again.", "error");
    } else {
      setStatus("Dropbox request failed: " + errorMessage(error), "error");
    }
  }

  function getDropboxFileExtension(fileName) {
    const lowerName = String(fileName || "").toLowerCase();
    const lastDot = lowerName.lastIndexOf(".");
    return lastDot >= 0 ? lowerName.slice(lastDot) : "";
  }

  function getDropboxFileKind(fileName) {
    const extension = getDropboxFileExtension(fileName);
    if (extension === ".pdf") return "pdf";
    if (extension === ".md") return "markdown";
    return "image";
  }

  function getDropboxFileTypeLabel(fileName) {
    const kind = getDropboxFileKind(fileName);
    if (kind === "pdf") return "PDF document";
    if (kind === "markdown") return "Markdown document";
    return "Image";
  }

  async function fetchAllSupportedFiles() {
    const entries = [];
    let response = await dbx.filesListFolder({
      path: "",
      recursive: true,
      limit: 2000
    });

    while (true) {
      const result = response.result;
      entries.push.apply(entries, result.entries || []);
      if (!result.has_more) break;
      response = await dbx.filesListFolderContinue({ cursor: result.cursor });
    }

    return entries
      .filter(function (entry) {
        return entry[".tag"] === "file" &&
          typeof entry.name === "string" &&
          SUPPORTED_FILE_EXTENSIONS.has(getDropboxFileExtension(entry.name)) &&
          typeof entry.path_lower === "string";
      })
      .sort(function (a, b) {
        return a.path_lower.localeCompare(b.path_lower);
      });
  }

  function makeDropboxFileIcon(file) {
    const kind = getDropboxFileKind(file.name);
    const wrapper = document.createElement("span");
    wrapper.className = "dropbox-file-icon";
    wrapper.dataset.kind = kind === "image" ? "image" : "document";
    wrapper.setAttribute("aria-hidden", "true");

    if (kind === "image") {
      wrapper.innerHTML = '<svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8.5" cy="9" r="1.5"/><path d="m4 17 5-5 3.5 3.5 2.5-2.5 5 5"/></svg>';
    } else {
      wrapper.innerHTML = '<svg viewBox="0 0 24 24"><path d="M6 2.75h8l4 4V21H6z"/><path d="M14 2.75v4h4M8.5 13h7M8.5 16.5h7"/></svg>';
    }
    return wrapper;
  }

  function selectDropboxFile(file, button) {
    if (!file || !button || isOpeningFile || isListingFiles) return;

    if (selectedDropboxButton && selectedDropboxButton !== button) {
      selectedDropboxButton.classList.remove("selected");
      selectedDropboxButton.setAttribute("aria-pressed", "false");
    }

    selectedDropboxFile = file;
    selectedDropboxButton = button;
    button.classList.add("selected");
    button.setAttribute("aria-pressed", "true");
    updateModalSelectButton();
    setStatus("Selected " + file.name + ". Choose Select File to open it.");
  }

  function renderSupportedFiles(files) {
    if (!modalFileList) return;
    modalFileList.replaceChildren();
    modalFileList.hidden = files.length === 0;
    clearDropboxSelection();

    if (!files.length) {
      setStatus("No supported files were found. Supported types: PDF, Markdown, JPG, PNG, SVG, WEBP and GIF.");
      return;
    }

    files.forEach(function (file) {
      const item = document.createElement("li");
      item.className = "dropbox-modal-file-item";

      const button = document.createElement("button");
      button.type = "button";
      button.className = "dropbox-file-button";
      button.title = file.path_display || file.path_lower;
      button.setAttribute("aria-pressed", "false");
      button.setAttribute("aria-label", "Select " + file.name);
      button.appendChild(makeDropboxFileIcon(file));

      const copy = document.createElement("span");
      copy.className = "dropbox-file-copy";

      const name = document.createElement("span");
      name.className = "dropbox-file-name";
      name.textContent = file.name;

      const path = document.createElement("span");
      path.className = "dropbox-file-path";
      path.textContent = (file.path_display || file.path_lower) + " · " + getDropboxFileTypeLabel(file.name);

      copy.append(name, path);

      const arrow = document.createElement("span");
      arrow.className = "dropbox-file-arrow";
      arrow.setAttribute("aria-hidden", "true");
      arrow.textContent = "›";

      button.append(copy, arrow);
      button.addEventListener("click", function () {
        selectDropboxFile(file, button);
      });

      item.appendChild(button);
      modalFileList.appendChild(item);
    });

    setStatus(files.length + (files.length === 1 ? " supported file found." : " supported files found.") +
      " Select one file, then choose Select File.");
  }

  async function openDropboxPicker() {
    if (!dbx) {
      await connectDropbox();
      return;
    }
    setModalOpen(true);
    await listDropboxSupportedFiles();
  }

  async function listDropboxSupportedFiles() {
    if (!dbx || isListingFiles || isOpeningFile) return;

    isListingFiles = true;
    clearDropboxSelection();
    if (modalFileList) {
      modalFileList.replaceChildren();
      modalFileList.hidden = true;
    }
    if (modalLoadingText) modalLoadingText.textContent = "Loading supported files from Dropbox…";
    setStatus("Loading supported files from Dropbox…");
    setModalLoading(true);

    try {
      const files = await fetchAllSupportedFiles();
      renderSupportedFiles(files);
    } catch (error) {
      handleRequestError(error);
    } finally {
      isListingFiles = false;
      setModalLoading(false);
      updateModalSelectButton();
    }
  }

  async function openSelectedDropboxFile() {
    const file = selectedDropboxFile;
    if (!dbx || isOpeningFile || isListingFiles || !file || !file.path_lower) return;

    isOpeningFile = true;
    updateModalSelectButton();
    updateSyncButton();
    if (modalLoadingText) modalLoadingText.textContent = "Downloading selected file…";
    setStatus("Opening " + file.name + "…");
    setModalLoading(true);

    try {
      const response = await dbx.filesDownload({ path: file.path_lower });
      const downloadedBlob = response && response.result && response.result.fileBlob;

      if (!(downloadedBlob instanceof Blob)) {
        throw new Error("Dropbox downloaded the file, but no file Blob was returned.");
      }

      const fileKind = getDropboxFileKind(file.name);
      activeFilePathLower = file.path_lower;
      activeFileName = file.name;
      activeFileKind = fileKind;
      activeSourcePdfBlob = fileKind === "pdf" ? downloadedBlob : null;
      editedPdfBlob = null;
      updateSyncButton();

      if (fileKind === "pdf") {
        window.dispatchEvent(new CustomEvent("lux:dropbox-pdf-loaded", {
          detail: {
            pdfBlob: downloadedBlob,
            fileName: activeFileName,
            pathLower: activeFilePathLower
          }
        }));
      } else {
        window.dispatchEvent(new CustomEvent("lux:dropbox-file-loaded", {
          detail: {
            fileBlob: downloadedBlob,
            fileName: activeFileName,
            fileKind: activeFileKind,
            pathLower: activeFilePathLower
          }
        }));
      }

      if (typeof window.loadPdfIntoViewer === "function") {
        await window.loadPdfIntoViewer(downloadedBlob, file.name);
      } else {
        await loadPdfIntoViewer(downloadedBlob, file.name);
      }

      setStatus("Opened " + file.name + ".");
      if (syncButton && fileKind === "pdf") {
        syncButton.title = "Sync changes to " + file.name + " in Dropbox";
        syncButton.textContent = "Sync";
      }
      setModalLoading(false);
      setModalOpen(false);
    } catch (error) {
      setModalLoading(false);
      handleRequestError(error);
    } finally {
      isOpeningFile = false;
      updateModalSelectButton();
      updateSyncButton();
    }
  }

  async function loadPdfIntoViewer(fileBlob, fileName) {
    const fileKind = getDropboxFileKind(fileName);
    if (fileKind === "pdf" && window.LuxPdfViewer && typeof window.LuxPdfViewer.loadPdf === "function") {
      await window.LuxPdfViewer.loadPdf(fileBlob, fileName);
      return;
    }

    if (!workspace) return;

    if (previewObjectUrl) URL.revokeObjectURL(previewObjectUrl);
    previewObjectUrl = URL.createObjectURL(fileBlob);
    workspace.replaceChildren();

    const heading = document.createElement("div");
    heading.className = "pdf-preview-heading";
    heading.textContent = fileName;

    if (fileKind === "image") {
      const image = document.createElement("img");
      image.className = "file-preview-image";
      image.alt = fileName;
      image.decoding = "async";
      image.src = previewObjectUrl;
      workspace.append(heading, image);
      return;
    }

    if (fileKind === "markdown") {
      const markdownPreview = document.createElement("pre");
      markdownPreview.className = "file-preview-markdown";
      markdownPreview.textContent = await fileBlob.text();
      workspace.append(heading, markdownPreview);
      return;
    }

    const note = document.createElement("p");
    note.className = "pdf-preview-note";
    note.textContent =
      "Browser preview only: PDF editing/export is not connected in this project build. Sync will not overwrite the source until an edited PDF Blob is provided.";

    const frame = document.createElement("iframe");
    frame.className = "pdf-preview-frame";
    frame.title = "PDF preview: " + fileName;
    frame.src = previewObjectUrl;

    workspace.append(heading, note, frame);
  }

  if (typeof window.loadPdfIntoViewer !== "function") {
    window.loadPdfIntoViewer = loadPdfIntoViewer;
  }

  async function getEditedPdfBlob() {
    if (window.LuxPdfViewer && typeof window.LuxPdfViewer.exportPdf === "function") {
      const exported = await window.LuxPdfViewer.exportPdf();
      if (exported instanceof Blob) return exported;
      throw new Error("The PDF editor export did not return a Blob. No Dropbox file was changed.");
    }

    if (editedPdfBlob instanceof Blob) return editedPdfBlob;

    throw new Error(
      "The current workspace only previews PDFs; its editing/export hook is not connected yet. " +
      "No Dropbox file was overwritten. Connect your editor through LuxDropboxIntegration.setEditedPdfBlob(blob)."
    );
  }

  async function syncToDropbox() {
    if (!dbx || !activeFilePathLower || activeFileKind !== "pdf" || isSyncing) return;

    isSyncing = true;
    if (syncFeedbackTimer) window.clearTimeout(syncFeedbackTimer);
    syncButton.textContent = "Syncing...";
    syncButton.title = "Syncing PDF to Dropbox";
    syncButton.disabled = true;
    setStatus("Preparing PDF to sync…");

    try {
      const blobToUpload = await getEditedPdfBlob();
      if (!(blobToUpload instanceof Blob)) {
        throw new Error("The PDF editor did not provide a Blob. No Dropbox file was changed.");
      }

      setConnectionStatus("uploading");
      setStatus("Uploading changes to Dropbox…");
      await dbx.filesUpload({
        path: activeFilePathLower,
        contents: blobToUpload,
        mode: { ".tag": "overwrite" }
      });

      editedPdfBlob = blobToUpload;
      setConnectionStatus("saved");
      syncButton.textContent = "Saved!";
      syncButton.title = "Saved to Dropbox";
      setStatus("Saved! Replaced " + activeFileName + " at its original Dropbox path.", "success");
      syncFeedbackTimer = window.setTimeout(function () {
        if (!isSyncing && syncButton.textContent === "Saved!") {
          syncButton.textContent = "Sync";
          syncButton.title = "Sync changes to " + activeFileName + " in Dropbox";
          setConnectionStatus(dbx ? "connected" : "not-connected");
        }
      }, 2200);
    } catch (error) {
      const detail = errorMessage(error);
      const isDropboxRequestFailure = Boolean(error && (typeof error.status === "number" || error.error));
      if (isDropboxRequestFailure) {
        handleRequestError(error);
      } else {
        // A missing editor export is not a Dropbox connection failure.
        setConnectionStatus(dbx ? "connected" : "not-connected");
        setStatus("Sync unavailable: " + detail, "error");
      }

      syncButton.textContent = isDropboxRequestFailure ? "Retry Sync" : "No edits";
      syncButton.title = detail;
      syncFeedbackTimer = window.setTimeout(function () {
        if (!isSyncing && (syncButton.textContent === "Retry Sync" || syncButton.textContent === "No edits")) {
          syncButton.textContent = "Sync";
          syncButton.title = activeFileName ? "Sync changes to " + activeFileName + " in Dropbox" : "Sync";
        }
      }, 3500);
    } finally {
      isSyncing = false;
      updateSyncButton();
    }
  }

  window.LuxDropboxIntegration = {
    setEditedPdfBlob: function (blob) {
      if (!(blob instanceof Blob)) {
        throw new TypeError("setEditedPdfBlob expects a Blob returned by the PDF editor.");
      }
      editedPdfBlob = blob;
      setStatus("Edited PDF is ready to sync.");
      updateSyncButton();
    },
    clearEditedPdfBlob: function () {
      editedPdfBlob = null;
      setStatus("Editor changes cleared; no updated PDF is ready to sync.");
    },
    discardActiveFile: function () {
      if (isOpeningFile || isSyncing) {
        setStatus("Wait for the current Dropbox operation to finish before discarding the document.", "error");
        return false;
      }

      if (syncFeedbackTimer) {
        window.clearTimeout(syncFeedbackTimer);
        syncFeedbackTimer = null;
      }
      if (previewObjectUrl) {
        URL.revokeObjectURL(previewObjectUrl);
        previewObjectUrl = null;
      }

      activeFilePathLower = null;
      activeFileName = null;
      activeFileKind = null;
      activeSourcePdfBlob = null;
      editedPdfBlob = null;
      updateSyncButton();
      setConnectionStatus(dbx ? "connected" : "not-connected");
      setStatus("Document discarded.");
      window.dispatchEvent(new CustomEvent("lux:dropbox-document-discarded"));
      return true;
    },
    getActiveFile: function () {
      if (!activeFilePathLower) return null;
      return {
        fileName: activeFileName,
        pathLower: activeFilePathLower,
        sourceBlob: activeSourcePdfBlob
      };
    },
    openPicker: openDropboxPicker
  };

  dropboxButton?.addEventListener("click", openDropboxPicker);
  syncButton?.addEventListener("click", syncToDropbox);

  accountToggle?.addEventListener("click", function (event) {
    event.stopPropagation();
    setAccountMenuOpen(Boolean(accountMenu && accountMenu.hidden));
  });

  accountMenu?.addEventListener("click", function (event) {
    event.stopPropagation();
  });

  menuConnectButton?.addEventListener("click", async function () {
    setAccountMenuOpen(false);
    await openDropboxPicker();
  });

  menuDisconnectButton?.addEventListener("click", function () {
    if (!dbx || isDisconnecting) return;
    setAccountFeedback("", "");
    if (disconnectConfirmation) disconnectConfirmation.hidden = false;
    menuDisconnectButton.hidden = true;
    disconnectConfirmButton?.focus();
  });

  disconnectCancelButton?.addEventListener("click", function () {
    if (disconnectConfirmation) disconnectConfirmation.hidden = true;
    if (menuDisconnectButton) menuDisconnectButton.hidden = !dbx;
    setAccountFeedback("", "");
    menuDisconnectButton?.focus();
  });

  disconnectConfirmButton?.addEventListener("click", async function () {
    if (isDisconnecting) return;
    isDisconnecting = true;
    disconnectConfirmButton.disabled = true;
    disconnectConfirmButton.textContent = "Disconnecting…";
    if (disconnectCancelButton) disconnectCancelButton.disabled = true;
    if (menuDisconnectButton) menuDisconnectButton.disabled = true;
    setAccountFeedback("Disconnecting Dropbox…", "");

    let tokenRevoked = false;
    try {
      if (dbx && typeof dbx.authTokenRevoke === "function") {
        await dbx.authTokenRevoke();
        tokenRevoked = true;
      }
    } catch (_) {
      // Always clear the browser session below, even if the revoke request fails.
    } finally {
      clearSessionCredentials("not-connected");
      isDisconnecting = false;
      if (disconnectConfirmation) disconnectConfirmation.hidden = true;
      if (menuDisconnectButton) {
        menuDisconnectButton.disabled = false;
        menuDisconnectButton.hidden = true;
      }
      if (disconnectCancelButton) disconnectCancelButton.disabled = false;
      if (disconnectConfirmButton) {
        disconnectConfirmButton.disabled = false;
        disconnectConfirmButton.textContent = "Disconnect";
      }

      if (tokenRevoked) {
        setAccountFeedback("Dropbox disconnected. Your session has been cleared and the access token was revoked.", "success");
      } else {
        setAccountFeedback("You are signed out of Luxy on this tab, but Dropbox could not confirm token revocation. To revoke access completely, remove Lux Omni from your Dropbox connected apps.", "error");
      }
    }
  });

  document.addEventListener("click", function (event) {
    if (
      accountMenu &&
      !accountMenu.hidden &&
      !accountMenu.contains(event.target) &&
      accountToggle &&
      !accountToggle.contains(event.target)
    ) {
      setAccountMenuOpen(false);
    }
  });

  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && accountMenu && !accountMenu.hidden) {
      setAccountMenuOpen(false);
      accountToggle?.focus();
    }
  });
  modalCloseButton?.addEventListener("click", function () {
    setModalOpen(false);
  });
  modalSelectButton?.addEventListener("click", openSelectedDropboxFile);
  modalCancelButton?.addEventListener("click", function () {
    setModalOpen(false);
  });
  modal?.querySelectorAll("[data-dropbox-modal-close]").forEach(function (element) {
    element.addEventListener("click", function () {
      setModalOpen(false);
    });
  });
  modal?.addEventListener("click", function (event) {
    if (event.target === modal) setModalOpen(false);
  });
  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && modal && !modal.hidden) {
      setModalOpen(false);
    }
  });

  async function initialize() {
    setConnectionStatus("not-connected");
    updateSyncButton();
    try {
      const callbackHandled = await handleOAuthCallback();
      if (!callbackHandled) restoreSession();
    } catch (error) {
      setConnectionStatus("connection-failed");
      setModalOpen(true);
      setStatus("Dropbox setup error: " + errorMessage(error), "error");
    }
  }

  initialize();
})();

site/styles.css.content:
:root {
  color-scheme: light;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;

  --ink: #1d2636;
  --muted: #758196;
  --line: #e5e9f0;
  --panel: #ffffff;
  --workspace: #f6f8fb;
  --accent: #4263eb;
  --brand-mark-bg: #eef2ff;
  --brand-name: #172033;

  --control-text: #273449;
  --control-bg: #ffffff;
  --control-border: #dce2ec;
  --control-hover-bg: #f7f8ff;
  --control-hover-border: #bac7ff;
  --focus-outline: #a5b4fc;
  --sidebar-width: 68px;
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --ink: #e8edf5;
  --muted: #a0aabd;
  --line: #303949;
  --panel: #181e29;
  --workspace: #10151e;
  --accent: #a5b4fc;
  --brand-mark-bg: #252d44;
  --brand-name: #f3f5fa;

  --control-text: #e7ecf5;
  --control-bg: #1d2533;
  --control-border: #3a4557;
  --control-hover-bg: #29344a;
  --control-hover-border: #6577b8;
  --focus-outline: #8195dc;
}

* {
  box-sizing: border-box;
}

html,
body {
  min-width: 320px;
  min-height: 100%;
  margin: 0;
}

body {
  min-height: 100vh;
  color: var(--ink);
  background: var(--workspace);
  transition: background-color 180ms ease, color 180ms ease;
}

button,
a {
  font: inherit;
}

.topbar {
  position: fixed;
  top: 0;
  right: 0;
  left: 0;
  z-index: 10;
  display: flex;
  width: 100%;
  min-height: 76px;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 12px 28px;
  border-bottom: 1px solid var(--line);
  background: var(--panel);
  transform: translateY(0);
  transition:
    transform 280ms cubic-bezier(0.22, 1, 0.36, 1),
    background-color 180ms ease,
    color 180ms ease,
    border-color 180ms ease;
}

.brand {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 12px;
  color: inherit;
  text-decoration: none;
}

.brand-mark {
  display: grid;
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  place-items: center;
  border-radius: 12px;
  color: var(--accent);
  background: transparent;
  transition: color 180ms ease;
}

.brand-mark img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}

.brand-name {
  overflow: hidden;
  color: var(--brand-name);
  font-size: 19px;
  font-weight: 720;
  letter-spacing: -0.035em;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.brand-slogan {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.25;
}

.topbar-actions {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 8px;
}

.dropbox-account {
  position: relative;
  display: inline-flex;
  min-width: 0;
  align-items: center;
}

.dropbox-topbar-status {
  display: inline-flex;
  min-width: 0;
  min-height: 40px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 7px;
  border: 1px solid transparent;
  border-radius: 9px;
  color: var(--control-text);
  background: transparent;
  cursor: pointer;
  font: inherit;
  white-space: nowrap;
  transition: background-color 180ms ease, border-color 180ms ease;
}

.dropbox-topbar-status:hover,
.dropbox-topbar-status[aria-expanded="true"] {
  border-color: var(--control-border);
  background: var(--control-hover-bg);
}

.dropbox-topbar-status:focus-visible,
.dropbox-menu-button:focus-visible {
  outline: 3px solid var(--focus-outline);
  outline-offset: 2px;
}

.dropbox-account-chevron {
  width: 13px;
  height: 13px;
  flex: 0 0 13px;
  fill: none;
  stroke: var(--muted);
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: transform 160ms ease;
}

.dropbox-topbar-status[aria-expanded="true"] .dropbox-account-chevron {
  transform: rotate(180deg);
}

.dropbox-account-menu {
  position: absolute;
  top: calc(100% + 10px);
  right: 0;
  z-index: 50;
  width: min(310px, calc(100vw - 24px));
  padding: 17px;
  border: 1px solid var(--line);
  border-radius: 14px;
  color: var(--ink);
  background: var(--panel);
  box-shadow: 0 18px 56px rgb(0 0 0 / 24%);
}

.dropbox-account-menu[hidden],
.dropbox-disconnect-confirmation[hidden] {
  display: none !important;
}

.dropbox-account-menu-heading {
  margin: 0 0 6px;
  color: var(--brand-name);
  font-size: 15px;
  font-weight: 750;
  letter-spacing: -.02em;
}

.dropbox-account-menu-description,
.dropbox-disconnect-confirmation p,
.dropbox-account-feedback {
  margin: 0 0 13px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.55;
  overflow-wrap: anywhere;
}

.dropbox-menu-button {
  display: inline-flex;
  min-height: 36px;
  align-items: center;
  justify-content: center;
  padding: 8px 12px;
  border: 1px solid var(--control-border);
  border-radius: 8px;
  color: var(--control-text);
  background: var(--control-bg);
  cursor: pointer;
  font-size: 12px;
  font-weight: 700;
}

.dropbox-menu-button:hover:not(:disabled) {
  background: var(--control-hover-bg);
  border-color: var(--control-hover-border);
}

.dropbox-menu-button:disabled {
  cursor: wait;
  opacity: .65;
}

.dropbox-menu-button-primary {
  width: 100%;
  border-color: #2469dc;
  color: #fff;
  background: #2469dc;
}

.dropbox-menu-button-primary:hover:not(:disabled) {
  border-color: #1e5ec9;
  background: #1e5ec9;
}

.dropbox-menu-button-danger {
  border-color: #c8414a;
  color: #fff;
  background: #c8414a;
}

.dropbox-menu-button-danger:hover:not(:disabled) {
  border-color: #ad3039;
  background: #ad3039;
}

.dropbox-disconnect-confirmation {
  margin-top: 12px;
  padding-top: 13px;
  border-top: 1px solid var(--line);
}

.dropbox-confirmation-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.dropbox-account-feedback {
  margin: 12px 0 0;
}

.dropbox-account-feedback[data-kind="success"] {
  color: #21865b;
}

.dropbox-account-feedback[data-kind="error"] {
  color: #d13f49;
}

.dropbox-status-logo {
  display: block;
  width: 20px;
  height: 20px;
  flex: 0 0 20px;
  fill: #2469dc;
}

.dropbox-status-text {
  max-width: 148px;
  overflow: hidden;
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dropbox-status-text[data-state="connected"] {
  color: #21865b;
}

.dropbox-status-text[data-state="connection-failed"] {
  color: #d13f49;
}

.dropbox-status-text[data-state="uploading"] {
  color: #2469dc;
}

.dropbox-status-text[data-state="saved"] {
  color: #21865b;
}

.theme-toggle,
.focus-toggle,
.sidebar-toggle {
  border: 1px solid var(--control-border);
  color: var(--control-text);
  background: var(--control-bg);
  cursor: pointer;
  transition: background-color 180ms ease, color 180ms ease, border-color 180ms ease;
}

.theme-toggle:hover,
.focus-toggle:hover,
.focus-toggle[aria-pressed="true"],
.dropbox-sync-button:hover:not(:disabled),
.sidebar-toggle:hover {
  border-color: var(--control-hover-border);
  background: var(--control-hover-bg);
}

.theme-toggle:focus-visible,
.focus-toggle:focus-visible,
.sidebar-toggle:focus-visible,
.dropbox-sync-button:focus-visible,
.brand:focus-visible {
  outline: 3px solid var(--focus-outline);
  outline-offset: 3px;
}

.theme-toggle {
  display: grid;
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  place-items: center;
  padding: 0;
  border-radius: 9px;
}

.theme-toggle svg {
  width: 19px;
  height: 19px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.7;
}

.theme-icon-sun {
  display: none;
}

:root[data-theme="dark"] .theme-icon-moon {
  display: none;
}

:root[data-theme="dark"] .theme-icon-sun {
  display: block;
}

.focus-toggle {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 11px;
  border-radius: 9px;
  white-space: nowrap;
}

.focus-toggle svg {
  width: 18px;
  height: 18px;
  flex: 0 0 18px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.8;
}

.focus-icon-exit {
  display: none;
}

body[data-focus-mode="true"] .focus-icon-enter {
  display: none;
}

body[data-focus-mode="true"] .focus-icon-exit {
  display: block;
}

/* Focus Mode only changes topbar visibility when the user enables it. */
body[data-focus-mode="true"] .topbar {
  transform: translateY(-100%);
  pointer-events: none;
}

body[data-focus-mode="true"] .topbar.is-visible {
  transform: translateY(0);
  pointer-events: auto;
}

.workspace-shell {
  position: relative;
  margin-top: 76px;
}

body[data-focus-mode="true"] .workspace-shell {
  margin-top: 0;
}

.sidebar-toggle-row {
  position: relative;
  z-index: 4;
  display: flex;
  width: var(--sidebar-width);
  height: 44px;
  align-items: center;
  padding: 0 12px;
  background: var(--workspace);
  pointer-events: none;
}

:root[data-sidebar-open="false"] .sidebar-toggle-row {
  background: transparent;
}

.sidebar-toggle {
  pointer-events: auto;
}

.viewport-composition {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: var(--sidebar-width);
  z-index: 2;
  display: grid;
  min-width: 0;
  min-height: 0;
  grid-template-columns: minmax(0, var(--split-left-share, 1fr)) 5px minmax(0, var(--split-right-share, 1fr));
  grid-template-rows: 44px minmax(0, 1fr) auto;
}

:root[data-sidebar-open="false"] .viewport-composition {
  left: 0;
}

.viewport-topbar {
  display: grid;
  grid-column: 1 / -1;
  grid-row: 1;
  min-width: 0;
  grid-template-columns: minmax(0, var(--split-left-share, 1fr)) 5px minmax(0, var(--split-right-share, 1fr));
  background: #d1d5db;
  border-bottom: 1px solid var(--line);
}

.viewport-toolbar-section {
  display: flex;
  min-width: 0;
  min-height: 0;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  padding: 0 8px;
}

.viewport-youtube-button {
  display: grid;
  width: 30px;
  height: 26px;
  flex: 0 0 30px;
  place-items: center;
  margin-right: auto;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 5px;
  background: transparent;
  cursor: pointer;
  transition: background-color 140ms ease, border-color 140ms ease;
}

.viewport-youtube-button:hover {
  border-color: rgb(255 0 51 / 20%);
  background: rgb(255 255 255 / 55%);
}

.viewport-youtube-button:focus-visible {
  outline: 2px solid #dc2626;
  outline-offset: 2px;
}

.viewport-youtube-button svg {
  display: block;
  width: 20px;
  height: 15px;
}

.viewport-toolbar-section--full {
  grid-column: 1 / -1;
}

.viewport-toolbar-section--left {
  grid-column: 1;
}

.viewport-toolbar-section--right {
  grid-column: 3;
}

.viewport-minimize-button,
.viewport-close-button {
  display: grid;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 4px;
  color: #ffffff;
  background: #dc2626;
  cursor: pointer;
  font-size: 20px;
  font-weight: 700;
  line-height: 1;
  transition: background-color 140ms ease, box-shadow 140ms ease;
}

.viewport-minimize-button {
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 4px;
  color: #ffffff;
  background: #6b7280;
  cursor: pointer;
  font-size: 22px;
  font-weight: 600;
  line-height: 1;
  transition: background-color 140ms ease, box-shadow 140ms ease;
}

.viewport-minimize-button:hover {
  background: #4b5563;
}

.viewport-minimize-button:focus-visible {
  outline: 2px solid #374151;
  outline-offset: 2px;
}

.viewport-close-button:hover {
  background: #b91c1c;
}

.viewport-close-button:focus-visible {
  outline: 2px solid #991b1b;
  outline-offset: 2px;
}

.sidebar-toggle {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  padding: 0;
  border-radius: 8px;
}

.sidebar-toggle svg {
  width: 19px;
  height: 19px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
}

.workspace-layout {
  display: grid;
  grid-template-columns: var(--sidebar-width) minmax(0, 1fr);
  min-height: calc(100vh - 120px);
  transition: grid-template-columns 240ms cubic-bezier(0.22, 1, 0.36, 1);
}

:root[data-sidebar-open="false"] .workspace-layout {
  grid-template-columns: 0 minmax(0, 1fr);
}

.sidebar {
  min-width: 0;
  overflow: hidden;
  border-right: 1px solid var(--line);
  background: var(--panel);
  transition: background-color 180ms ease, border-color 180ms ease;
}

:root[data-sidebar-open="false"] .sidebar {
  border-right-color: transparent;
}

.sidebar-inner {
  width: var(--sidebar-width);
  min-width: var(--sidebar-width);
  min-height: calc(100vh - 120px);
  height: 100%;
  padding: 12px 8px;
  overflow-x: hidden;
}

.workspace {
  min-width: 0;
  min-height: calc(100vh - 120px);
  background: var(--workspace);
}

.viewport-stage {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
}

.viewport-stage--full {
  grid-column: 1 / -1;
  grid-row: 2;
}

.viewport-stage--split {
  display: contents;
}

.viewport-stage--split > .viewport:first-child {
  grid-column: 1;
  grid-row: 2;
}

.viewport-stage--split > .viewport:last-child {
  grid-column: 3;
  grid-row: 2;
}

.viewport-composition[data-mode^="solo-"] {
  grid-template-columns: minmax(0, 1fr) 0 minmax(0, 0fr);
}

.viewport-composition[data-mode^="solo-"] .viewport-topbar {
  grid-template-columns: minmax(0, 1fr) 0 minmax(0, 0fr);
}

.viewport-composition[data-mode^="solo-"] .viewport-stage--split > .viewport {
  display: none;
}

.viewport-composition[data-mode="solo-left"] .viewport-stage--split > .viewport[data-viewport-side="left"],
.viewport-composition[data-mode="solo-right"] .viewport-stage--split > .viewport[data-viewport-side="right"] {
  display: block;
  grid-column: 1 / -1;
  grid-row: 2;
}

.viewport-number {
  position: relative;
  z-index: 4;
  display: grid;
  width: 25px;
  height: 30px;
  align-self: center;
  justify-self: end;
  place-items: center;
  margin-right: 7px;
  border: 1px solid #94a3b8;
  border-radius: 5px;
  color: #111827;
  background: #ffffff;
  box-shadow: 0 1px 3px rgb(15 23 42 / 12%);
  font-size: 11px;
  font-weight: 750;
  line-height: 1;
  pointer-events: none;
  grid-row: 2;
}

.viewport-number--full {
  grid-column: 1 / -1;
}

.viewport-number--left {
  grid-column: 1;
}

.viewport-number--right {
  grid-column: 3;
}

.viewport-composition[data-mode="solo-right"] .viewport-number--right {
  grid-column: 1 / -1;
}

.viewport-minimized-dock {
  display: flex;
  min-width: 0;
  max-width: 100%;
  grid-column: 1 / -1;
  grid-row: 3;
  align-items: center;
  padding: 7px 9px;
  border-top: 1px solid var(--line);
  background: var(--workspace);
}

.viewport-minimized-items {
  display: flex;
  min-width: 0;
  max-width: 100%;
  flex: 1 1 auto;
  flex-wrap: wrap;
  gap: 7px;
}

.viewport-minimized-bar {
  display: grid;
  width: min(100%, 340px);
  min-width: min(220px, 100%);
  min-height: 34px;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  padding: 0 10px;
  border: 1px solid var(--control-border);
  border-radius: 7px;
  color: var(--control-text);
  background: var(--panel);
  cursor: pointer;
  text-align: left;
  box-shadow: 0 1px 3px rgb(15 23 42 / 8%);
}

.viewport-minimized-bar:hover {
  border-color: var(--control-hover-border);
  background: var(--control-hover-bg);
}

.viewport-minimized-bar:focus-visible {
  outline: 2px solid var(--focus-outline);
  outline-offset: 2px;
}

.viewport-minimized-file {
  overflow: hidden;
  font-size: 12px;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.viewport-minimized-number {
  color: var(--muted);
  font-size: 11px;
  font-weight: 750;
  white-space: nowrap;
}

.viewport-minimized-restore {
  color: var(--muted);
  font-size: 17px;
  line-height: 1;
}

.viewport-composition.is-minimized-only {
  pointer-events: none;
}

.viewport-composition.is-minimized-only .viewport-minimized-dock {
  pointer-events: auto;
}

.viewport-split-divider {
  position: relative;
  z-index: 5;
  grid-column: 2;
  grid-row: 1 / 3;
  width: 5px;
  cursor: col-resize;
  touch-action: none;
  user-select: none;
}

.viewport-split-divider::before {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 2px;
  width: 1px;
  background: var(--line);
  content: "";
  transition: background-color 160ms ease;
}

.viewport-split-divider:hover::before,
.viewport-split-divider:focus-visible::before,
.viewport-split-divider:active::before {
  background: var(--accent);
}

.viewport {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: scroll;
  border: 1px solid var(--line);
  background: #ffffff;
}

.viewport-youtube-content {
  display: grid;
  width: 100%;
  min-height: 100%;
  place-items: start center;
  padding: 12px;
  background: #ffffff;
}

.viewport-youtube-frame {
  display: block;
  width: min(100%, 960px);
  height: auto;
  aspect-ratio: 16 / 9;
  border: 0;
  background: #000000;
}

.viewport-youtube-error {
  margin: 12px;
  color: #dc2626;
  font-size: 13px;
  line-height: 1.5;
}

.sidebar-cloud-actions {
  display: flex;
  width: 100%;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}

.dropbox-button {
  display: inline-flex;
  width: 100%;
  min-height: 42px;
  align-items: center;
  justify-content: flex-start;
  gap: 11px;
  padding: 10px 12px;
  border: 1px solid var(--control-border);
  border-radius: 10px;
  color: var(--control-text);
  background: var(--control-bg);
  cursor: pointer;
  text-align: left;
  font-weight: 650;
  transition: background-color 180ms ease, color 180ms ease, border-color 180ms ease, opacity 180ms ease;
}

.dropbox-icon-button {
  display: grid;
  width: 40px;
  height: 40px;
  min-height: 40px;
  flex: 0 0 40px;
  place-items: center;
  justify-content: center;
  padding: 0;
  border-radius: 9px;
}

.dropbox-icon-button .dropbox-logo,
.dropbox-icon-button .clipboard-icon {
  width: 22px;
  height: 22px;
}

.clipboard-icon {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.viewport-mode-button .viewport-mode-icon {
  width: 22px;
  height: 22px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.dropbox-button:hover:not(:disabled) {
  border-color: var(--control-hover-border);
  background: var(--control-hover-bg);
}

.dropbox-button:focus-visible,
.dropbox-file-button:focus-visible,
.dropbox-modal-close:focus-visible,
.dropbox-modal-action:focus-visible {
  outline: 3px solid var(--focus-outline);
  outline-offset: 2px;
}

.dropbox-button-primary {
  border-color: #2469dc;
  color: #fff;
  background: #2469dc;
}

.dropbox-button-primary:hover:not(:disabled) {
  border-color: #1e5ec9;
  background: #1e5ec9;
}

.dropbox-button:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}

.dropbox-logo {
  display: block;
  width: 21px;
  height: 21px;
  flex: 0 0 21px;
  fill: currentColor;
}

.dropbox-sync-button {
  width: auto;
  min-width: 58px;
  height: 40px;
  min-height: 40px;
  flex: 0 0 auto;
  justify-content: center;
  padding: 0 12px;
  border-radius: 9px;
  color: var(--control-text);
  background: var(--control-bg);
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
}

.visually-hidden {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

.dropbox-modal {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: grid;
  align-items: center;
  justify-items: center;
  padding: 24px;
}

.dropbox-modal[hidden] {
  display: none !important;
}

.dropbox-modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgb(8 13 25 / 64%);
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
}

.dropbox-modal-panel {
  position: relative;
  z-index: 1;
  display: flex;
  width: min(100%, 680px);
  max-height: min(82vh, 760px);
  min-height: min(280px, 65vh);
  flex-direction: column;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  color: var(--ink);
  background: var(--panel);
  box-shadow: 0 24px 80px rgb(0 0 0 / 32%);
  animation: dropbox-modal-appear 170ms ease-out;
}

@keyframes dropbox-modal-appear {
  from { opacity: 0; transform: translateY(8px) scale(.99); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.dropbox-modal-header {
  display: flex;
  flex: 0 0 auto;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: 22px 24px 18px;
  border-bottom: 1px solid var(--line);
}

.dropbox-modal-eyebrow {
  margin: 0 0 5px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 750;
  letter-spacing: .1em;
  text-transform: uppercase;
}

.dropbox-modal-header h2 {
  margin: 0;
  color: var(--brand-name);
  font-size: clamp(20px, 4vw, 25px);
  font-weight: 750;
  letter-spacing: -.035em;
  line-height: 1.2;
}

.dropbox-modal-close {
  display: grid;
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  place-items: center;
  padding: 0;
  border: 1px solid var(--control-border);
  border-radius: 10px;
  color: var(--control-text);
  background: var(--control-bg);
  cursor: pointer;
}

.dropbox-modal-close:hover {
  border-color: var(--control-hover-border);
  background: var(--control-hover-bg);
}

.dropbox-modal-close svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
}

.dropbox-modal-status {
  flex: 0 0 auto;
  margin: 0;
  padding: 14px 24px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}

.dropbox-modal-status[data-kind="error"] {
  color: #c44545;
}

.dropbox-modal-status[data-kind="success"] {
  color: #21865b;
}

.dropbox-modal-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 11px;
  padding: 32px 20px 42px;
  color: var(--muted);
  font-size: 14px;
}

.dropbox-spinner {
  width: 19px;
  height: 19px;
  flex: 0 0 19px;
  border: 2px solid var(--control-border);
  border-top-color: #2469dc;
  border-radius: 50%;
  animation: dropbox-spin .75s linear infinite;
}

@keyframes dropbox-spin {
  to { transform: rotate(360deg); }
}

.dropbox-modal-loading[hidden],
.dropbox-modal-file-list[hidden] {
  display: none !important;
}

.dropbox-modal-file-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 220px), 1fr));
  align-content: start;
  min-height: 0;
  flex: 1 1 auto;
  gap: 10px;
  margin: 0;
  padding: 0 18px 18px;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  list-style: none;
}

.dropbox-modal-file-item {
  min-width: 0;
}

.dropbox-file-button {
  display: flex;
  width: 100%;
  min-height: 78px;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  color: var(--control-text);
  background: var(--control-bg);
  cursor: pointer;
  text-align: left;
  transition: border-color 160ms ease, background-color 160ms ease, box-shadow 160ms ease;
}

.dropbox-file-button:hover {
  border-color: var(--control-hover-border);
  background: var(--control-hover-bg);
}

.dropbox-file-button.selected,
.dropbox-file-button[aria-pressed="true"] {
  border-color: #2469dc;
  background: rgb(36 105 220 / 11%);
  box-shadow: inset 0 0 0 1px rgb(36 105 220 / 40%);
}

.dropbox-file-button.selected .dropbox-file-name,
.dropbox-file-button[aria-pressed="true"] .dropbox-file-name {
  color: var(--ink);
}

.dropbox-file-icon {
  display: grid;
  width: 40px;
  height: 42px;
  flex: 0 0 40px;
  place-items: center;
  border-radius: 9px;
  color: #dc3c44;
  background: rgb(220 60 68 / 10%);
}

.dropbox-file-icon[data-kind="image"] {
  color: #16845d;
  background: rgb(22 132 93 / 12%);
}

.dropbox-file-icon[data-kind="document"] {
  color: #3268c9;
  background: rgb(50 104 201 / 11%);
}

.dropbox-file-icon svg {
  width: 22px;
  height: 22px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.dropbox-file-copy {
  display: flex;
  min-width: 0;
  flex: 1 1 auto;
  flex-direction: column;
  gap: 5px;
}

.dropbox-file-name {
  display: -webkit-box;
  overflow: hidden;
  color: var(--ink);
  font-size: 13px;
  font-weight: 650;
  line-height: 1.4;
  overflow-wrap: anywhere;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.dropbox-file-path {
  overflow: hidden;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.4;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dropbox-file-arrow {
  flex: 0 0 auto;
  color: var(--muted);
  font-size: 19px;
}

.dropbox-modal-footer {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding: 14px 24px;
  border-top: 1px solid var(--line);
  background: var(--panel);
}

.dropbox-modal-footer .dropbox-button {
  width: auto;
  min-width: 112px;
  justify-content: center;
  text-align: center;
}

.dropbox-modal-footer .dropbox-button:disabled {
  cursor: not-allowed;
  opacity: 0.48;
}

.dropbox-modal-close:disabled {
  cursor: wait;
  opacity: 0.65;
}

body.dropbox-modal-open {
  overflow: hidden;
}

.workspace-empty-state {
  display: flex;
  min-height: 50vh;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 32px;
  color: var(--muted);
  text-align: center;
}

.workspace-empty-state h1 {
  margin: 0;
  color: var(--ink);
  font-size: clamp(21px, 3vw, 30px);
  letter-spacing: -0.04em;
}

.workspace-empty-state p {
  max-width: 620px;
  margin: 0;
  font-size: 14px;
  line-height: 1.6;
}

.pdf-preview-frame {
  display: block;
  width: 100%;
  height: calc(100vh - 150px);
  min-height: 500px;
  border: 0;
  background: var(--panel);
}

.pdf-preview-heading {
  padding: 14px 18px;
  border-bottom: 1px solid var(--line);
  color: var(--ink);
  font-size: 14px;
  font-weight: 650;
  overflow-wrap: anywhere;
}

.pdf-preview-note {
  margin: 0;
  padding: 11px 18px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.5;
}

.file-preview-image {
  display: block;
  max-width: min(100%, 1200px);
  max-height: calc(100vh - 180px);
  margin: 0 auto;
  object-fit: contain;
}

.file-preview-markdown {
  max-width: 100%;
  margin: 0;
  padding: 20px;
  overflow: auto;
  color: var(--ink);
  background: var(--panel);
  font: 13px/1.65 ui-monospace, SFMono-Regular, Consolas, monospace;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

body[data-focus-mode="true"] .workspace-layout,
body[data-focus-mode="true"] .sidebar-inner,
body[data-focus-mode="true"] .workspace {
  min-height: calc(100vh - 44px);
}

[hidden] {
  display: none !important;
}

.site-footer {
  display: flex;
  min-height: 42px;
  align-items: center;
  justify-content: flex-end;
  padding: 8px 18px;
  border-top: 1px solid var(--line);
  background: var(--panel);
  font-size: 12px;
}
.site-footer a {
  color: var(--muted);
  text-decoration: none;
}
.site-footer a:hover {
  color: var(--accent);
  text-decoration: underline;
}

@media (max-width: 560px) {
  .topbar {
    gap: 10px;
    padding-right: 10px;
    padding-left: 10px;
  }

  .topbar-actions {
    gap: 5px;
  }

  .dropbox-account-menu {
    right: -4px;
    padding: 15px;
  }

  .dropbox-topbar-status {
    gap: 4px;
    padding: 0;
  }

  .dropbox-status-logo {
    width: 17px;
    height: 17px;
    flex-basis: 17px;
  }

  .dropbox-status-text {
    max-width: 92px;
    font-size: 10px;
  }

  .dropbox-sync-button {
    min-width: 48px;
    padding: 0 8px;
    font-size: 11px;
  }

  .dropbox-modal {
    padding: 12px;
  }

  .dropbox-modal-panel {
    max-height: 88vh;
    min-height: min(220px, 60vh);
    border-radius: 15px;
  }

  .dropbox-modal-header {
    padding: 17px 17px 15px;
  }

  .dropbox-modal-status {
    padding: 12px 17px;
  }

  .dropbox-modal-file-list {
    padding: 0 12px 14px;
  }

  .dropbox-modal-footer {
    padding: 12px 17px;
  }

  .dropbox-modal-footer .dropbox-button {
    min-width: 90px;
    padding: 9px 10px;
  }

  .topbar {
    min-height: 68px;
    gap: 10px;
    padding: 10px 12px;
  }

  .brand {
    gap: 8px;
  }

  .brand-mark {
    width: 36px;
    height: 36px;
    flex-basis: 36px;
    border-radius: 10px;
  }

  .brand-mark svg {
    width: 28px;
    height: 28px;
  }

  .brand-name {
    font-size: 15px;
  }

  .brand-slogan {
    max-width: 180px;
    font-size: 10px;
  }

  .focus-toggle {
    width: 40px;
    min-width: 40px;
    padding: 0;
    gap: 0;
  }

  .focus-toggle span {
    display: none;
  }

  .workspace-shell {
    margin-top: 68px;
  }

  body[data-focus-mode="true"] .workspace-shell {
    margin-top: 0;
  }

  .workspace-layout {
    min-height: calc(100vh - 112px);
  }

  .sidebar-inner,
  .workspace {
    min-height: calc(100vh - 112px);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

site/app.js.content:
// Lux Omni core interface controls.
// Dark Mode, Focus Mode, and the manually controlled sidebar only.

const themeToggle = document.querySelector("#theme-toggle");
const focusModeToggle = document.querySelector("#focus-mode-toggle");
const sidebarToggle = document.querySelector("#sidebar-toggle");
const topbar = document.querySelector(".topbar");
const fullScreenViewportButton = document.querySelector("#viewport-fullscreen");
const splitScreenViewportButton = document.querySelector("#viewport-split-screen");
const workspace = document.querySelector(".workspace");
const workspaceEmptyState = workspace?.querySelector(".workspace-empty-state");
const viewportComposition = document.querySelector("#viewport-composition");
const fullScreenViewportLayout = document.querySelector("#viewport-fullscreen-layout");
const splitScreenViewportLayout = document.querySelector("#viewport-split-layout");
const viewportTopbar = document.querySelector("#viewport-topbar");
const viewportToolbarFull = document.querySelector("#viewport-toolbar-full");
const viewportToolbarLeft = document.querySelector("#viewport-toolbar-left");
const viewportToolbarRight = document.querySelector("#viewport-toolbar-right");
const viewportNumberFull = document.querySelector("#viewport-number-full");
const viewportNumberLeft = document.querySelector("#viewport-number-left");
const viewportNumberRight = document.querySelector("#viewport-number-right");
const viewportMinimizedDock = document.querySelector("#viewport-minimized-dock");
const viewportMinimizedItems = document.querySelector("#viewport-minimized-items");
const splitViewportDivider = document.querySelector("#viewport-split-divider");

const viewportMinimizeFullButton = document.querySelector("#viewport-minimize-full");
const viewportMinimizeLeftButton = document.querySelector("#viewport-minimize-left");
const viewportMinimizeRightButton = document.querySelector("#viewport-minimize-right");
const viewportYoutubeFullButton = document.querySelector("#viewport-youtube-full");
const viewportYoutubeLeftButton = document.querySelector("#viewport-youtube-left");
const viewportYoutubeRightButton = document.querySelector("#viewport-youtube-right");

const THEME_STORAGE_KEY = "lux-pdf-viewer-theme";
const FOCUS_MODE_STORAGE_KEY = "lux-pdf-viewer-focus-mode";
const SIDEBAR_STORAGE_KEY = "lux-pdf-viewer-sidebar-open";

// Dark Mode
function setDarkMode(enabled, savePreference = true) {
  if (enabled) {
    document.documentElement.setAttribute("data-theme", "dark");
  } else {
    document.documentElement.removeAttribute("data-theme");
  }

  themeToggle?.setAttribute("aria-pressed", String(enabled));
  themeToggle?.setAttribute(
    "aria-label",
    enabled ? "Switch to white mode" : "Switch to dark mode"
  );
  themeToggle?.setAttribute(
    "title",
    enabled ? "Switch to white mode" : "Switch to dark mode"
  );

  if (savePreference) {
    try {
      localStorage.setItem(THEME_STORAGE_KEY, enabled ? "dark" : "light");
    } catch {
      // Theme switching remains available while this page is open.
    }
  }
}

let savedDarkMode = document.documentElement.getAttribute("data-theme") === "dark";
try {
  savedDarkMode = localStorage.getItem(THEME_STORAGE_KEY) === "dark";
} catch {
  // Use the theme initialized in the HTML.
}
setDarkMode(savedDarkMode, false);

themeToggle?.addEventListener("click", () => {
  const enabled = document.documentElement.getAttribute("data-theme") === "dark";
  setDarkMode(!enabled);
});

// Focus Mode
function isFocusModeEnabled() {
  return document.body.dataset.focusMode === "true";
}

function showTopbar() {
  if (isFocusModeEnabled()) topbar?.classList.add("is-visible");
}

function hideTopbar() {
  if (isFocusModeEnabled()) topbar?.classList.remove("is-visible");
}

function setFocusMode(enabled, savePreference = true) {
  document.body.dataset.focusMode = String(enabled);
  topbar?.classList.remove("is-visible");

  focusModeToggle?.setAttribute("aria-pressed", String(enabled));
  focusModeToggle?.setAttribute(
    "aria-label",
    enabled ? "Turn off Focus Mode" : "Turn on Focus Mode"
  );
  focusModeToggle?.setAttribute(
    "title",
    enabled ? "Turn off Focus Mode" : "Turn on Focus Mode"
  );

  if (savePreference) {
    try {
      localStorage.setItem(FOCUS_MODE_STORAGE_KEY, String(enabled));
    } catch {
      // Focus Mode remains available while this page is open.
    }
  }

  lastScrollY = window.scrollY;
}

let savedFocusMode = document.body.dataset.focusMode === "true";
try {
  const storedFocusMode = localStorage.getItem(FOCUS_MODE_STORAGE_KEY);
  if (storedFocusMode === "true" || storedFocusMode === "false") {
    savedFocusMode = storedFocusMode === "true";
  }
} catch {
  // Use the state initialized in the HTML.
}
let lastScrollY = window.scrollY;
setFocusMode(savedFocusMode, false);

focusModeToggle?.addEventListener("click", () => {
  setFocusMode(!isFocusModeEnabled());
});

window.addEventListener(
  "scroll",
  () => {
    const currentScrollY = window.scrollY;

    if (isFocusModeEnabled()) {
      if (currentScrollY < lastScrollY || currentScrollY <= 10) {
        showTopbar();
      } else if (currentScrollY > lastScrollY) {
        hideTopbar();
      }
    } else {
      topbar?.classList.remove("is-visible");
    }

    lastScrollY = currentScrollY;
  },
  { passive: true }
);

document.addEventListener("mousemove", (event) => {
  if (isFocusModeEnabled() && event.clientY <= 10) showTopbar();
});

topbar?.addEventListener("mouseenter", showTopbar);
topbar?.addEventListener("mouseleave", hideTopbar);
topbar?.addEventListener("focusin", showTopbar);

// Sidebar: only the user's button controls its state; scrolling and hover do nothing.
function setSidebarOpen(isOpen, savePreference = true) {
  document.documentElement.setAttribute("data-sidebar-open", String(isOpen));
  sidebarToggle?.setAttribute("aria-expanded", String(isOpen));
  sidebarToggle?.setAttribute(
    "aria-label",
    isOpen ? "Close sidebar" : "Open sidebar"
  );
  sidebarToggle?.setAttribute(
    "title",
    isOpen ? "Close sidebar" : "Open sidebar"
  );

  if (savePreference) {
    try {
      localStorage.setItem(SIDEBAR_STORAGE_KEY, String(isOpen));
    } catch {
      // Sidebar toggling remains available while this page is open.
    }
  }
}

let savedSidebarOpen = document.documentElement.getAttribute("data-sidebar-open") !== "false";
try {
  const storedSidebarState = localStorage.getItem(SIDEBAR_STORAGE_KEY);
  if (storedSidebarState === "true" || storedSidebarState === "false") {
    savedSidebarOpen = storedSidebarState === "true";
  }
} catch {
  // Use the state initialized in the HTML.
}
setSidebarOpen(savedSidebarOpen, false);

sidebarToggle?.addEventListener("click", () => {
  const isOpen = document.documentElement.getAttribute("data-sidebar-open") === "true";
  setSidebarOpen(!isOpen);
});

// Viewport layouts, minimize/restore, and close controls.
let activeViewportMode = null;
let soloSplitSide = null;
let rememberedSplitRatio = 0.5;
const minimizedViewportStates = new Map();

function getViewportElement(side) {
  if (side === "full") {
    return fullScreenViewportLayout?.querySelector(':scope > .viewport[data-viewport-side="full"]') ||
      fullScreenViewportLayout?.querySelector(":scope > .viewport") ||
      null;
  }
  return splitScreenViewportLayout?.querySelector(`:scope > .viewport[data-viewport-side="${side}"]`) || null;
}

function createSplitViewport(side) {
  const viewport = document.createElement("div");
  viewport.className = "viewport viewport--split";
  viewport.dataset.viewportSide = side;
  return viewport;
}

function ensureSplitViewports() {
  if (!splitScreenViewportLayout) return;

  if (!getViewportElement("left")) {
    splitScreenViewportLayout.prepend(createSplitViewport("left"));
  }
  if (!getViewportElement("right")) {
    splitScreenViewportLayout.append(createSplitViewport("right"));
  }
}

function ensureFullViewport() {
  if (!fullScreenViewportLayout || getViewportElement("full")) return;

  const viewport = document.createElement("div");
  viewport.className = "viewport";
  viewport.dataset.viewportSide = "full";
  fullScreenViewportLayout.append(viewport);
}

function getViewportNumber(side) {
  if (side === "left") return "1/2";
  if (side === "right") return "2/2";
  return "0";
}

function getViewportFileName(side) {
  const viewport = getViewportElement(side);
  const explicitName = viewport?.dataset.fileName?.trim();
  const headingName = viewport?.querySelector(".pdf-preview-heading")?.textContent?.trim();
  const ariaName = viewport?.getAttribute("aria-label")?.trim();
  let activeFileName = "";
  try {
    activeFileName = window.LuxDropboxIntegration?.getActiveFile?.()?.fileName?.trim() || "";
  } catch {
    // The viewport can still be minimized before a cloud file is connected.
  }
  return explicitName || headingName || ariaName || activeFileName || "Untitled";
}

function renderMinimizedViewportDock() {
  if (!viewportMinimizedDock || !viewportMinimizedItems) return;

  viewportMinimizedItems.replaceChildren();
  const order = ["full", "left", "right"];
  for (const side of order) {
    const savedState = minimizedViewportStates.get(side);
    if (!savedState) continue;

    const fileName = getViewportFileName(side);
    const number = getViewportNumber(side);
    const button = document.createElement("button");
    button.className = "viewport-minimized-bar";
    button.type = "button";
    button.setAttribute("aria-label", `Restore viewport ${number}, ${fileName}`);
    button.title = `Restore viewport ${number}`;

    const numberLabel = document.createElement("span");
    numberLabel.className = "viewport-minimized-number";
    numberLabel.textContent = number;

    const fileLabel = document.createElement("span");
    fileLabel.className = "viewport-minimized-file";
    fileLabel.textContent = fileName;

    const restoreMark = document.createElement("span");
    restoreMark.className = "viewport-minimized-restore";
    restoreMark.setAttribute("aria-hidden", "true");
    restoreMark.textContent = "↗";

    button.append(numberLabel, fileLabel, restoreMark);
    button.addEventListener("click", () => restoreMinimizedViewport(side));
    viewportMinimizedItems.append(button);
  }

  viewportMinimizedDock.hidden = minimizedViewportStates.size === 0;
}

function renderViewportComposition() {
  if (!viewportComposition || !fullScreenViewportLayout || !splitScreenViewportLayout) return;

  const isFull = activeViewportMode === "full";
  const isSplit = activeViewportMode === "split";
  const isSolo = activeViewportMode === "solo";
  const hasActiveViewport = activeViewportMode !== null;
  const hasMinimizedViewports = minimizedViewportStates.size > 0;

  viewportComposition.dataset.mode = isSolo ? `solo-${soloSplitSide}` : (activeViewportMode || "minimized");
  viewportComposition.hidden = !hasActiveViewport && !hasMinimizedViewports;
  viewportComposition.classList.toggle("is-minimized-only", !hasActiveViewport && hasMinimizedViewports);

  fullScreenViewportLayout.hidden = !isFull;
  splitScreenViewportLayout.hidden = !(isSplit || isSolo);
  if (viewportTopbar) viewportTopbar.hidden = !hasActiveViewport;
  if (viewportToolbarFull) viewportToolbarFull.hidden = !(isFull || isSolo);
  if (viewportToolbarLeft) viewportToolbarLeft.hidden = !isSplit;
  if (viewportToolbarRight) viewportToolbarRight.hidden = !isSplit;
  if (splitViewportDivider) splitViewportDivider.hidden = !isSplit;

  if (viewportNumberFull) viewportNumberFull.hidden = !isFull;
  if (viewportNumberLeft) viewportNumberLeft.hidden = !(isSplit || (isSolo && soloSplitSide === "left"));
  if (viewportNumberRight) viewportNumberRight.hidden = !(isSplit || (isSolo && soloSplitSide === "right"));

  fullScreenViewportButton?.setAttribute("aria-pressed", String(isFull || isSolo));
  splitScreenViewportButton?.setAttribute("aria-pressed", String(isSplit));

  const soloLabel = soloSplitSide === "left" ? "left" : "right";
  viewportMinimizeFullButton?.setAttribute("aria-label", isSolo ? `Minimize ${soloLabel} viewport` : "Minimize full-screen viewport");
  viewportMinimizeFullButton?.setAttribute("title", isSolo ? `Minimize ${soloLabel} viewport` : "Minimize viewport");
  document.querySelector("#viewport-close-full")?.setAttribute("aria-label", isSolo ? `Close ${soloLabel} viewport` : "Close full-screen viewport");
  document.querySelector("#viewport-close-full")?.setAttribute("title", isSolo ? `Close ${soloLabel} viewport` : "Close viewport");

  renderMinimizedViewportDock();
}

function showNormalWorkspaceAfterViewportClose(clearWorkspace = false) {
  if (!workspaceEmptyState || !workspace) return;
  if (clearWorkspace) {
    workspace.replaceChildren(workspaceEmptyState);
  }
  if (workspace.contains(workspaceEmptyState)) workspaceEmptyState.hidden = false;
}

function setViewportMode(mode) {
  if (!workspace || !viewportComposition || !fullScreenViewportLayout || !splitScreenViewportLayout) return;

  if (mode === "full") {
    ensureFullViewport();
    minimizedViewportStates.delete("full");
    activeViewportMode = "full";
    soloSplitSide = null;
  } else {
    ensureSplitViewports();
    // Explicitly opening Split Screen restores both original split panes.
    minimizedViewportStates.delete("left");
    minimizedViewportStates.delete("right");
    activeViewportMode = "split";
    soloSplitSide = null;
    setSplitViewportRatio(rememberedSplitRatio);
  }

  if (workspaceEmptyState) workspaceEmptyState.hidden = true;
  renderViewportComposition();
}

function rememberMinimizedViewport(side, originalMode) {
  const viewport = getViewportElement(side);
  if (!viewport) return;

  minimizedViewportStates.set(side, {
    side,
    originalMode,
    splitRatio: rememberedSplitRatio
  });
}

function minimizeFullScreenViewport() {
  if (activeViewportMode === "solo" && soloSplitSide) {
    minimizeSplitViewport(soloSplitSide);
    return;
  }
  if (activeViewportMode !== "full") return;

  rememberMinimizedViewport("full", "full");
  activeViewportMode = null;
  soloSplitSide = null;
  renderViewportComposition();
  showNormalWorkspaceAfterViewportClose(false);
}

function minimizeSplitViewport(side) {
  if (activeViewportMode === "split") {
    const currentRatio = Number(splitViewportDivider?.getAttribute("aria-valuenow") || "50") / 100;
    rememberedSplitRatio = currentRatio;
    rememberMinimizedViewport(side, "split");
    activeViewportMode = "solo";
    soloSplitSide = side === "left" ? "right" : "left";
  } else if (activeViewportMode === "solo" && soloSplitSide === side) {
    rememberMinimizedViewport(side, "split");
    activeViewportMode = null;
    soloSplitSide = null;
  } else {
    return;
  }

  renderViewportComposition();
  if (!activeViewportMode) showNormalWorkspaceAfterViewportClose(false);
}

function restoreMinimizedViewport(side) {
  const savedState = minimizedViewportStates.get(side);
  if (!savedState) return;

  if (side === "full" || savedState.originalMode === "full") {
    // Keep any currently visible split viewport(s) minimized when restoring Full Screen.
    if (activeViewportMode === "solo" && soloSplitSide) {
      rememberMinimizedViewport(soloSplitSide, "split");
    } else if (activeViewportMode === "split") {
      rememberMinimizedViewport("left", "split");
      rememberMinimizedViewport("right", "split");
    }

    minimizedViewportStates.delete("full");
    activeViewportMode = "full";
    soloSplitSide = null;
  } else {
    const otherSplitSide = side === "left" ? "right" : "left";
    const restoringPair =
      activeViewportMode === "solo" &&
      soloSplitSide === otherSplitSide &&
      minimizedViewportStates.has(side);

    if (restoringPair) {
      // The other split pane is already visible. Restoring its minimized partner
      // returns both panes to their original side-by-side layout.
      minimizedViewportStates.delete("left");
      minimizedViewportStates.delete("right");
      ensureSplitViewports();
      rememberedSplitRatio = savedState.splitRatio || rememberedSplitRatio;
      setSplitViewportRatio(rememberedSplitRatio);
      activeViewportMode = "split";
      soloSplitSide = null;
    } else {
      if (activeViewportMode === "full") {
        rememberMinimizedViewport("full", "full");
      }

      minimizedViewportStates.delete(side);
      ensureSplitViewports();
      rememberedSplitRatio = savedState.splitRatio || rememberedSplitRatio;
      setSplitViewportRatio(rememberedSplitRatio);
      activeViewportMode = "solo";
      soloSplitSide = side;
    }
  }

  if (workspaceEmptyState) workspaceEmptyState.hidden = true;
  renderViewportComposition();
}

function clearActiveDropboxDocument() {
  const integration = window.LuxDropboxIntegration;
  if (integration && typeof integration.discardActiveFile === "function") {
    return integration.discardActiveFile() !== false;
  }
  return true;
}

function closeFullScreenViewport() {
  if (activeViewportMode === "solo" && soloSplitSide) {
    closeSplitViewport(soloSplitSide);
    return;
  }
  if (activeViewportMode !== "full" || !window.confirm("Discard documents?")) return;
  if (!clearActiveDropboxDocument()) return;

  getViewportElement("full")?.replaceChildren();
  activeViewportMode = null;
  soloSplitSide = null;
  renderViewportComposition();
  showNormalWorkspaceAfterViewportClose(minimizedViewportStates.size === 0);
}

function closeSplitViewport(side) {
  const isSplit = activeViewportMode === "split";
  const isCurrentSoloSide = activeViewportMode === "solo" && soloSplitSide === side;
  if ((!isSplit && !isCurrentSoloSide) || !window.confirm("Discard documents?")) return;
  if (!clearActiveDropboxDocument()) return;

  getViewportElement(side)?.replaceChildren();
  minimizedViewportStates.delete(side);

  if (isSplit) {
    activeViewportMode = "solo";
    soloSplitSide = side === "left" ? "right" : "left";
  } else {
    activeViewportMode = null;
    soloSplitSide = null;
  }

  renderViewportComposition();
  if (!activeViewportMode) showNormalWorkspaceAfterViewportClose(minimizedViewportStates.size === 0);
}

fullScreenViewportButton?.addEventListener("click", () => setViewportMode("full"));
splitScreenViewportButton?.addEventListener("click", () => setViewportMode("split"));
viewportMinimizeFullButton?.addEventListener("click", minimizeFullScreenViewport);
viewportMinimizeLeftButton?.addEventListener("click", () => minimizeSplitViewport("left"));
viewportMinimizeRightButton?.addEventListener("click", () => minimizeSplitViewport("right"));
document.querySelector("#viewport-close-full")?.addEventListener("click", closeFullScreenViewport);
document.querySelector("#viewport-close-left")?.addEventListener("click", () => closeSplitViewport("left"));
document.querySelector("#viewport-close-right")?.addEventListener("click", () => closeSplitViewport("right"));

const YOUTUBE_URL_REGEX = /(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/|youtube\.com\/shorts\/)([^"&?\/\s]{11})/i;

function loadYoutubeVideoIntoViewport(requestedSide) {
  // The shared Full Screen toolbar also represents whichever split pane is
  // currently expanded alone.
  const side = activeViewportMode === "solo" && soloSplitSide
    ? soloSplitSide
    : requestedSide;
  const viewport = getViewportElement(side);
  if (!viewport) return;

  const userInput = window.prompt("Paste a YouTube video link:", "");
  if (userInput === null) return;

  const match = userInput.match(YOUTUBE_URL_REGEX);
  viewport.replaceChildren();

  if (!match || !match[1]) {
    delete viewport.dataset.fileName;
    const errorMessage = document.createElement("p");
    errorMessage.className = "viewport-youtube-error";
    errorMessage.textContent = "Invalid link! Please paste a valid YouTube video link.";
    viewport.append(errorMessage);
    return;
  }

  const videoId = match[1];
  const embedUrl = `https://www.youtube.com/embed/${videoId}`;
  const content = document.createElement("div");
  content.className = "viewport-youtube-content";

  const frame = document.createElement("iframe");
  frame.className = "viewport-youtube-frame";
  frame.src = embedUrl;
  frame.title = "YouTube video player";
  frame.setAttribute("frameborder", "0");
  frame.setAttribute("allow", "accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share");
  frame.setAttribute("allowfullscreen", "");
  content.append(frame);
  viewport.dataset.fileName = `YouTube video ${videoId}`;
  viewport.append(content);
  viewport.scrollTop = 0;
}

viewportYoutubeFullButton?.addEventListener("click", () => loadYoutubeVideoIntoViewport("full"));
viewportYoutubeLeftButton?.addEventListener("click", () => loadYoutubeVideoIntoViewport("left"));
viewportYoutubeRightButton?.addEventListener("click", () => loadYoutubeVideoIntoViewport("right"));

// Resize the two split viewports by dragging the narrow vertical divider.
function setSplitViewportRatio(ratio) {
  if (!splitScreenViewportLayout || !splitViewportDivider) return;

  const boundedRatio = Math.max(0.2, Math.min(0.8, ratio));
  rememberedSplitRatio = boundedRatio;
  viewportComposition?.style.setProperty("--split-left-share", boundedRatio + "fr");
  viewportComposition?.style.setProperty("--split-right-share", (1 - boundedRatio) + "fr");
  splitViewportDivider.setAttribute("aria-valuenow", String(Math.round(boundedRatio * 100)));
}

if (splitViewportDivider && splitScreenViewportLayout && viewportComposition) {
  let activePointerId = null;

  function updateSplitRatioFromPointer(event) {
    if (event.pointerId !== activePointerId) return;

    const layoutBounds = viewportComposition.getBoundingClientRect();
    const dividerWidth = splitViewportDivider.getBoundingClientRect().width;
    const usableWidth = layoutBounds.width - dividerWidth;
    if (usableWidth <= 0) return;

    const leftWidth = event.clientX - layoutBounds.left - dividerWidth / 2;
    setSplitViewportRatio(leftWidth / usableWidth);
  }

  function stopSplitResize() {
    if (activePointerId === null) return;
    splitViewportDivider.removeEventListener("pointermove", updateSplitRatioFromPointer);
    splitViewportDivider.removeEventListener("pointerup", stopSplitResize);
    splitViewportDivider.removeEventListener("pointercancel", stopSplitResize);
    if (splitViewportDivider.hasPointerCapture(activePointerId)) {
      splitViewportDivider.releasePointerCapture(activePointerId);
    }
    activePointerId = null;
  }

  splitViewportDivider.addEventListener("pointerdown", (event) => {
    if (!event.isPrimary || (event.pointerType === "mouse" && event.button !== 0)) return;
    event.preventDefault();

    activePointerId = event.pointerId;
    splitViewportDivider.setPointerCapture(activePointerId);
    splitViewportDivider.addEventListener("pointermove", updateSplitRatioFromPointer);
    splitViewportDivider.addEventListener("pointerup", stopSplitResize);
    splitViewportDivider.addEventListener("pointercancel", stopSplitResize);
  });

  splitViewportDivider.addEventListener("keydown", (event) => {
    const currentRatio = Number(splitViewportDivider.getAttribute("aria-valuenow") || "50") / 100;
    if (event.key === "ArrowLeft") {
      event.preventDefault();
      setSplitViewportRatio(currentRatio - 0.02);
    } else if (event.key === "ArrowRight") {
      event.preventDefault();
      setSplitViewportRatio(currentRatio + 0.02);
    } else if (event.key === "Home") {
      event.preventDefault();
      setSplitViewportRatio(0.2);
    } else if (event.key === "End") {
      event.preventDefault();
      setSplitViewportRatio(0.8);
    }
  });
}
